// ═══════════════════════════════════════════════════════════════════════════
//  POST /webhook/zk/roster-publish  ·  n8n Code node
//  Mode: "Run Once for All Items". Sits between the Webhook and the Data table
//  Upsert node, which writes to `zk_roster`.
//
//  Called by dataiku/publish_roster.py, never by a device. It flattens what
//  Dataiku sends into one row per record so the Data table node can upsert them
//  keyed on `key`.
//
//  Devices read the same table through roster-response.js. Nothing here ever
//  touches Snowflake - it cannot; see SYNC-DESIGN.md section 3.2.
// ═══════════════════════════════════════════════════════════════════════════

const first = $input.first().json || {};
const body = first.body || first;

const employees = Array.isArray(body.employees) ? body.employees : [];
const departments = Array.isArray(body.departments) ? body.departments : [];

const rows = [];

for (const e of employees) {
  const pin = String(e.pin || '').trim();
  if (!pin) continue;

  // The whole record is stored as one JSON blob rather than as columns.
  // Deliberate: the roster shape will change again - it already gained split
  // names once - and n8n Data table columns are edited by hand in the UI, so
  // every added field would be a manual migration on a live instance. The
  // device parses this; n8n only needs to filter on `version` and key on
  // `key`, which are the two things kept as real columns.
  rows.push({
    key: 'emp:' + pin,
    kind: 'employee',
    version: Number(e.version) || 0,
    payload: JSON.stringify({
      pin,
      firstName: e.firstName || '',
      lastName: e.lastName || '',
      fullName: e.fullName || '',
      department: e.department || '',
      gender: e.gender || '',
      deleted: e.deleted === true,
      version: Number(e.version) || 0,
      fingers: Array.isArray(e.fingers) ? e.fingers : [],
    }),
  });
}

for (const d of departments) {
  const name = String(d.name || '').trim();
  if (!name) continue;
  rows.push({
    key: 'dept:' + name,
    kind: 'department',
    version: Number(d.version) || 0,
    payload: JSON.stringify({
      name,
      deleted: d.deleted === true,
      version: Number(d.version) || 0,
    }),
  });
}

// alwaysOutputData on the Data table node covers the empty case, but emit a
// sentinel anyway: n8n skips a node that receives zero items, which would leave
// the Respond node unreached and hang Dataiku until its timeout.
if (!rows.length) {
  return [{ json: { noop: true, count: 0 } }];
}

return rows.map(row => ({ json: row }));

// ═══════════════════════════════════════════════════════════════════════════
//  GET /webhook/zk/roster?since=<version>&sn=<device_sn>  ·  n8n Code node
//  Mode: "Run Once for All Items". Sits between the Data table Get node
//  (reading `zk_roster`) and the Respond node.
//
//  This is what a terminal calls to ask "what has changed since I last looked?"
//  It reads only what dataiku/publish_roster.py parked in the Data table - n8n
//  never queries Snowflake, and a device never reaches it.
// ═══════════════════════════════════════════════════════════════════════════

const items = $input.all().map(i => i.json).filter(Boolean);

// Read `since` from the webhook node by name, NOT from $input.
//
// $input here is the Data table's rows; the webhook item is not in it. Hunting
// for an item carrying `query` - which this file did first - finds nothing,
// silently falls back to 0, and returns the entire roster on every single poll.
// Every device would then re-apply every row forever: correct output, endless
// work, and templates re-registered into the matcher on a loop.
let since = 0;
try {
  const q = $('Roster Pull').first().json.query || {};
  since = Number(q.since || q.Since || 0) || 0;
} catch (e) {
  // Node renamed or unreachable. 0 means "send everything", which is wasteful
  // but correct - better than dropping rows a device has not seen.
  since = 0;
}

const rows = items.filter(r => r && r.key && r.payload);

function parse(row) {
  try {
    const payload = typeof row.payload === 'string' ? JSON.parse(row.payload) : row.payload;
    return { version: Number(row.version) || 0, kind: row.kind, payload };
  } catch (e) {
    // A row that will not parse is skipped rather than thrown on. One corrupt
    // record must not stop every terminal in the fleet from syncing, and it is
    // visible in the count mismatch between `employees` and the table size.
    return null;
  }
}

const parsed = rows.map(parse).filter(Boolean);

// Strictly greater than: `since` is the highest version the device already
// holds, so returning it again would make every poll re-apply the same rows
// and re-register the same templates into the matcher for no reason.
const changed = parsed.filter(r => r.version > since);

const employees = changed
  .filter(r => r.kind === 'employee')
  .map(r => r.payload)
  // Ascending, so a device applying them in order ends on the newest state for
  // anyone who changed twice between polls.
  .sort((a, b) => (a.version || 0) - (b.version || 0));

const departments = changed
  .filter(r => r.kind === 'department')
  .map(r => r.payload)
  .sort((a, b) => (a.version || 0) - (b.version || 0));

// The watermark is the highest version in the WHOLE table, not just in what we
// are returning. If it were the max of `changed`, a device that received an
// empty page would keep its old `since` forever and re-scan the same range on
// every poll. It is only advanced by the device after it has applied the batch
// successfully - a crash halfway through must re-fetch, not skip.
const version = parsed.reduce((max, r) => (r.version > max ? r.version : max), since);

return [{
  json: {
    version,
    employees,
    departments,
    counts: {
      employees: employees.length,
      departments: departments.length,
      total: parsed.length,
    },
  },
}];
